def outlier_analysis(df: pd.DataFrame) -> Dict[str, Any]:
    """
    Identify outliers using standardized residuals and Cook's D.
    
    Returns:
        Dictionary with outlier info and recomputed correlations
    """
    log("[OUTLIER] Starting outlier analysis...")
    
    # Compute standardized residuals for BVMT ~ Where relationship
    X_where = df[['Where_mean']].values
    y_bvmt = df['bvmt_total'].values
    
    # Fit linear model
    reg_where = LinearRegression().fit(X_where, y_bvmt)
    residuals_where = y_bvmt - reg_where.predict(X_where)
    
    # Standardized residuals (Z-scores)
    std_residuals_where = np.abs(stats.zscore(residuals_where))
    
    # Identify outliers (|z| > 3.29, corresponds to p < 0.001)
    outlier_threshold = 3.29
    outliers_where = np.where(std_residuals_where > outlier_threshold)[0]
    
    log(f"[OUTLIER] Found {len(outliers_where)} outliers using threshold {outlier_threshold}")
    
    # Remove outliers and recompute correlations
    if len(outliers_where) > 0:
        df_clean = df.drop(df.index[outliers_where]).reset_index(drop=True)
        log(f"[OUTLIER] Dataset size after outlier removal: {len(df_clean)} (removed {len(outliers_where)})")
    else:
        df_clean = df.copy()
        log("[OUTLIER] No outliers detected")
    
    # Recompute correlations without outliers
    r_bvmt_where_clean = stats.pearsonr(df_clean['bvmt_total'], df_clean['Where_mean'])[0]
    r_bvmt_what_clean = stats.pearsonr(df_clean['bvmt_total'], df_clean['What_mean'])[0]
    
    # Original correlations for comparison
    r_bvmt_where_orig = stats.pearsonr(df['bvmt_total'], df['Where_mean'])[0]
    r_bvmt_what_orig = stats.pearsonr(df['bvmt_total'], df['What_mean'])[0]
    
    return {
        'n_outliers': len(outliers_where),
        'outlier_indices': outliers_where.tolist(),
        'n_clean': len(df_clean),
        'r_bvmt_where_original': r_bvmt_where_orig,
        'r_bvmt_what_original': r_bvmt_what_orig,
        'r_bvmt_where_clean': r_bvmt_where_clean,
        'r_bvmt_what_clean': r_bvmt_what_clean,
        'where_change': r_bvmt_where_clean - r_bvmt_where_orig,
        'what_change': r_bvmt_what_clean - r_bvmt_what_orig
    }

def alternative_correlation_methods(df: pd.DataFrame) -> Dict[str, Any]:
    """
    Compute Spearman and Kendall correlations for comparison with Pearson.
    
    Returns:
        Dictionary with alternative correlation results
    """
    log("[METHODS] Computing alternative correlation methods...")
    
    # Spearman correlations
    spear_bvmt_where = stats.spearmanr(df['bvmt_total'], df['Where_mean'])
    spear_bvmt_what = stats.spearmanr(df['bvmt_total'], df['What_mean'])
    
    # Kendall correlations  
    kendall_bvmt_where = stats.kendalltau(df['bvmt_total'], df['Where_mean'])
    kendall_bvmt_what = stats.kendalltau(df['bvmt_total'], df['What_mean'])
    
    # Pearson for comparison
    pearson_bvmt_where = stats.pearsonr(df['bvmt_total'], df['Where_mean'])
    pearson_bvmt_what = stats.pearsonr(df['bvmt_total'], df['What_mean'])
    
    log(f"[METHODS] Spearman BVMT-Where: r={spear_bvmt_where.correlation:.3f}, p={spear_bvmt_where.pvalue:.3f}")
    log(f"[METHODS] Kendall BVMT-Where: tau={kendall_bvmt_where.correlation:.3f}, p={kendall_bvmt_where.pvalue:.3f}")
    
    return {
        'pearson_bvmt_where': pearson_bvmt_where.statistic,
        'pearson_bvmt_what': pearson_bvmt_what.statistic,
        'spearman_bvmt_where': spear_bvmt_where.correlation,
        'spearman_bvmt_what': spear_bvmt_what.correlation,
        'kendall_bvmt_where': kendall_bvmt_where.correlation,
        'kendall_bvmt_what': kendall_bvmt_what.correlation,
        'spearman_where_pvalue': spear_bvmt_where.pvalue,
        'spearman_what_pvalue': spear_bvmt_what.pvalue,
        'kendall_where_pvalue': kendall_bvmt_where.pvalue,
        'kendall_what_pvalue': kendall_bvmt_what.pvalue
    }

def cross_validation_analysis(df: pd.DataFrame, cv_folds: int = 5, seed: int = 42) -> Dict[str, Any]:
    """
    Perform k-fold cross-validation to assess correlation stability.
    
    Returns:
        Dictionary with CV statistics
    """
    log(f"[CV] Starting {cv_folds}-fold cross-validation...")
    
    # Set up cross-validation
    kf = KFold(n_splits=cv_folds, shuffle=True, random_state=seed)
    
    # Storage for CV results
    cv_r_bvmt_where = []
    cv_r_bvmt_what = []
    
    # Perform cross-validation
    for i, (train_idx, val_idx) in enumerate(kf.split(df)):
        df_fold = df.iloc[val_idx]
        
        # Compute correlations on fold
        r_where = stats.pearsonr(df_fold['bvmt_total'], df_fold['Where_mean'])[0]
        r_what = stats.pearsonr(df_fold['bvmt_total'], df_fold['What_mean'])[0]
        
        cv_r_bvmt_where.append(r_where)
        cv_r_bvmt_what.append(r_what)
        
        log(f"[CV] Fold {i+1}: r_where={r_where:.3f}, r_what={r_what:.3f}")
    
    # Compute CV statistics
    cv_r_bvmt_where = np.array(cv_r_bvmt_where)
    cv_r_bvmt_what = np.array(cv_r_bvmt_what)
    
    return {
        'cv_folds': cv_folds,
        'mean_r_bvmt_where': np.mean(cv_r_bvmt_where),
        'std_r_bvmt_where': np.std(cv_r_bvmt_where),
        'mean_r_bvmt_what': np.mean(cv_r_bvmt_what),
        'std_r_bvmt_what': np.std(cv_r_bvmt_what),
        'cv_correlations_where': cv_r_bvmt_where.tolist(),
        'cv_correlations_what': cv_r_bvmt_what.tolist(),
        'stability_ratio_where': np.std(cv_r_bvmt_where) / np.abs(np.mean(cv_r_bvmt_where)),
        'stability_ratio_what': np.std(cv_r_bvmt_what) / np.abs(np.mean(cv_r_bvmt_what))
    }

def power_analysis(df: pd.DataFrame, alpha: float = 0.00179) -> Dict[str, Any]:
    """
    Conduct post-hoc power analysis for observed correlations.
    
    Parameters:
        alpha: Corrected alpha level (Bonferroni correction)
    
    Returns:
        Dictionary with power analysis results
    """
    log(f"[POWER] Conducting power analysis with alpha={alpha}")
    
    n = len(df)
    
    # Observed correlations
    r_bvmt_where = stats.pearsonr(df['bvmt_total'], df['Where_mean'])[0]
    r_bvmt_what = stats.pearsonr(df['bvmt_total'], df['What_mean'])[0]
    
    # Fisher's z-transformation for effect size
    z_where = 0.5 * np.log((1 + r_bvmt_where) / (1 - r_bvmt_where))
    z_what = 0.5 * np.log((1 + r_bvmt_what) / (1 - r_bvmt_what))
    
    # Standard error for correlation
    se_r = 1.0 / np.sqrt(n - 3)
    
    # Critical z-value for two-tailed test
    z_critical = stats.norm.ppf(1 - alpha/2)
    
    # Power calculation: Probability of detecting effect
    # Power = P(|Z| > z_critical | effect exists)
    power_where = 1 - stats.norm.cdf(z_critical - np.abs(z_where)/se_r) + stats.norm.cdf(-z_critical - np.abs(z_where)/se_r)
    power_what = 1 - stats.norm.cdf(z_critical - np.abs(z_what)/se_r) + stats.norm.cdf(-z_critical - np.abs(z_what)/se_r)
    
    # Minimum detectable effect (80% power)
    z_80 = stats.norm.ppf(0.8)  # 80% power
    min_detectable_z = (z_critical + z_80) * se_r
    min_detectable_r = np.tanh(min_detectable_z)  # Convert back from Fisher's z
    
    log(f"[POWER] Power for Where correlation: {power_where:.3f}")
    log(f"[POWER] Power for What correlation: {power_what:.3f}")
    log(f"[POWER] Minimum detectable correlation (80% power): {min_detectable_r:.3f}")
    
    return {
        'n': n,
        'alpha': alpha,
        'r_bvmt_where': r_bvmt_where,
        'r_bvmt_what': r_bvmt_what,
        'power_where': power_where,
        'power_what': power_what,
        'z_critical': z_critical,
        'se_correlation': se_r,
        'min_detectable_r_80pct': min_detectable_r,
        'adequately_powered_where': power_where >= 0.80,
        'adequately_powered_what': power_what >= 0.80
    }

